package com.agentic.shortener;

import com.agentic.IntegrationTest;
import com.agentic.shortener.ShortenerExceptions.Gone;
import com.agentic.shortener.ShortenerFixtures.MutableClock;
import com.agentic.shortener.domain.ClickEventRepository;
import com.agentic.shortener.domain.ShortUrlRepository;
import com.agentic.shortener.service.ShortCodeGenerator;
import com.agentic.shortener.service.ShortenerService;
import com.agentic.shortener.service.ShortenerService.CreateCommand;
import com.agentic.shortener.service.UrlValidator;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.time.Duration;
import java.time.Instant;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Regression tests for "expired links still redirect sometimes": ShortenerService enforces expiry on every redirect,
 * including for links that are already in the redirect cache.
 */
class ExpiryDefectTest extends IntegrationTest {

    @Autowired
    ShortUrlRepository urls;
    @Autowired
    ClickEventRepository clicks;

    private final ShortenerProperties props = ShortenerFixtures.properties();
    private final MutableClock clock = new MutableClock(Instant.parse("2026-03-01T10:00:00Z"));

    private ShortenerService service() {
        return new ShortenerService(urls, clicks, new ShortCodeGenerator(props), new UrlValidator(props), clock, props);
    }

    private String cachedLinkExpiringInSeconds(ShortenerService service, long seconds) {
        String code = service.create(new CreateCommand("https://example.com/t", null, clock.instant().plusSeconds(seconds), null)).getShortCode();
        service.resolve(code);   // load it into the redirect cache while it is still valid
        return code;
    }

    @Test
    void aCachedLinkStopsRedirectingOnceItHasExpired() {
        ShortenerService service = service();
        String code = cachedLinkExpiringInSeconds(service, 60);

        clock.advance(Duration.ofSeconds(120));

        assertThatThrownBy(() -> service.resolve(code)).isInstanceOf(Gone.class).hasMessageContaining("expired");
    }

    @Test
    void aLinkExpiringExactlyNowIsGone() {
        ShortenerService service = service();
        String code = cachedLinkExpiringInSeconds(service, 60);

        clock.advance(Duration.ofSeconds(60));

        assertThatThrownBy(() -> service.resolve(code)).isInstanceOf(Gone.class);
    }

    @Test
    void aLinkKeepsRedirectingUntilItExpires() {
        ShortenerService service = service();
        String code = cachedLinkExpiringInSeconds(service, 60);

        clock.advance(Duration.ofSeconds(59));

        assertThat(service.resolve(code).originalUrl()).isEqualTo("https://example.com/t");
    }

    @Test
    void aLinkWithoutAnExpiryNeverExpires() {
        ShortenerService service = service();
        String code = service.create(new CreateCommand("https://example.com/forever", null, null, null)).getShortCode();
        service.resolve(code);

        clock.advance(Duration.ofDays(3650));

        assertThat(service.resolve(code).originalUrl()).isEqualTo("https://example.com/forever");
    }
}

package com.agentic.shortener.service;

import com.agentic.IntegrationTest;
import com.agentic.shortener.ShortenerExceptions.InvalidRequest;
import com.agentic.shortener.service.ShortenerService.BatchItemResult;
import com.agentic.shortener.service.ShortenerService.CreateCommand;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.util.ArrayList;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Rules of ShortenerService.createBatch: independence of items, ordering, and the limit of 100. */
class ShortenerServiceBatchTest extends IntegrationTest {

    @Autowired
    ShortenerService service;

    private static CreateCommand command(String url, String alias) {
        return new CreateCommand(url, alias, null, null);
    }

    @Test
    void validItemsAreCreatedAndInvalidOnesAreReportedWithTheirIndex() {
        List<BatchItemResult> results = service.createBatch(List.of(
                command("https://example.com/a", null),
                command("javascript:alert(1)", null),
                command("https://example.com/c", "my-batch-alias")));

        assertThat(results).extracting(BatchItemResult::index).containsExactly(0, 1, 2);
        assertThat(results.get(0).link()).isNotNull();
        assertThat(results.get(1).link()).isNull();
        assertThat(results.get(1).error()).contains("http");
        assertThat(results.get(2).link().getShortCode()).isEqualTo("my-batch-alias");
    }

    @Test
    void aDuplicateAliasInsideOneBatchRejectsOnlyTheSecondItem() {
        List<BatchItemResult> results = service.createBatch(List.of(
                command("https://example.com/1", "same-alias"),
                command("https://example.com/2", "same-alias")));

        assertThat(results.get(0).link()).isNotNull();
        assertThat(results.get(1).link()).isNull();
        assertThat(results.get(1).error()).contains("already in use");
    }

    @Test
    void anEmptyBatchIsRejected() {
        assertThatThrownBy(() -> service.createBatch(List.of())).isInstanceOf(InvalidRequest.class);
        assertThatThrownBy(() -> service.createBatch(null)).isInstanceOf(InvalidRequest.class);
    }

    @Test
    void exactlyTheMaximumIsAcceptedAndOneMoreIsNot() {
        List<CreateCommand> max = new ArrayList<>();
        for (int i = 0; i < ShortenerService.MAX_BATCH_SIZE; i++) {
            max.add(command("https://example.com/" + i, null));
        }
        assertThat(service.createBatch(max)).hasSize(100).allMatch(r -> r.link() != null);

        max.add(command("https://example.com/one-too-many", null));
        assertThatThrownBy(() -> service.createBatch(max)).isInstanceOf(InvalidRequest.class).hasMessageContaining("100");
    }
}

package com.agentic.shortener;

import com.agentic.IntegrationTest;
import com.agentic.shortener.web.ShortenerDtos;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import tools.jackson.databind.json.JsonMapper;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/** Exercises UrlController.createBulk over HTTP. */
@AutoConfigureMockMvc
class BulkApiTest extends IntegrationTest {

    private final JsonMapper mapper = JsonMapper.builder().build();

    @Autowired
    MockMvc mvc;

    private ShortenerDtos.BulkCreateResponse bulk(String body) throws Exception {
        String json = mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        return mapper.readValue(json, ShortenerDtos.BulkCreateResponse.class);
    }

    @Test
    void createsTheValidItemsAndReportsTheInvalidOnes() throws Exception {
        ShortenerDtos.BulkCreateResponse response = bulk(
                "{\"urls\":[{\"url\":\"https://example.com/a\"},{\"url\":\"ftp://nope.example\"},{\"url\":\"https://example.com/c\",\"customAlias\":\"bulk-c\"}]}");

        assertThat(response.created()).isEqualTo(2);
        assertThat(response.rejected()).isEqualTo(1);
        assertThat(response.items()).extracting(ShortenerDtos.BulkItem::status).containsExactly("CREATED", "REJECTED", "CREATED");
        assertThat(response.items().get(1).error()).contains("http");
        assertThat(response.items().get(2).code()).isEqualTo("bulk-c");
        mvc.perform(get("/bulk-c")).andExpect(status().isFound());
    }

    @Test
    void anEmptyListIsRejected() throws Exception {
        mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content("{\"urls\":[]}"))
                .andExpect(status().isBadRequest());
        mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content("{}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void moreThanOneHundredItemsAreRejected() throws Exception {
        StringBuilder body = new StringBuilder("{\"urls\":[");
        for (int i = 0; i < 101; i++) {
            body.append(i == 0 ? "" : ",").append("{\"url\":\"https://example.com/").append(i).append("\"}");
        }
        body.append("]}");
        mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content(body.toString()))
                .andExpect(status().isBadRequest());
    }

    @Test
    void exactlyOneHundredItemsAreAccepted() throws Exception {
        StringBuilder body = new StringBuilder("{\"urls\":[");
        for (int i = 0; i < 100; i++) {
            body.append(i == 0 ? "" : ",").append("{\"url\":\"https://example.com/").append(i).append("\"}");
        }
        body.append("]}");
        assertThat(bulk(body.toString()).created()).isEqualTo(100);
    }
}

package com.agentic.shortener;

import com.agentic.IntegrationTest;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/** CreateRateLimitFilter must limit POST /api/v1/urls/bulk too, otherwise bulk would be a way around the limit. */
@AutoConfigureMockMvc
@TestPropertySource(properties = "shortener.create-rate-limit-per-minute=2")
class BulkRateLimitTest extends IntegrationTest {

    @Autowired
    MockMvc mvc;

    @Test
    void bulkAndSingleCreatesShareTheSameLimit() throws Exception {
        String bulk = "{\"urls\":[{\"url\":\"https://example.com/a\"}]}";
        mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content(bulk)).andExpect(status().isOk());
        mvc.perform(post("/api/v1/urls").contentType(MediaType.APPLICATION_JSON).content("{\"url\":\"https://example.com/b\"}"))
                .andExpect(status().isCreated());
        mvc.perform(post("/api/v1/urls/bulk").contentType(MediaType.APPLICATION_JSON).content(bulk))
                .andExpect(status().isTooManyRequests())
                .andExpect(header().string("Retry-After", "60"));
    }
}
